import { describe, test } from 'node:test'
import assert from 'node:assert/strict'
import {
  serializeLoadAddons,
  splitAddonBootstrap,
} from './lazy-addon-bootstrap.js'

/** What an addon's `pikku all` writes to `.pikku/addon/pikku-bootstrap.gen.ts`. */
const addonBootstrap = `/**
 * This file was generated by @pikku/cli@0.12.190
 */
import './rpc/pikku-rpc-wirings-meta.internal.gen.js'
import './function/pikku-functions-meta.gen.js'
import './permissions/pikku-permissions.gen.js'
import './pikku-package.gen.js'
import './schemas/register.gen.js'
import './function/pikku-functions.gen.js'
`

describe('splitAddonBootstrap', () => {
  test('defers the function and schema registrations, keeps the meta', () => {
    assert.deepEqual(splitAddonBootstrap('@acme/addon', addonBootstrap), {
      eager: [
        '@acme/addon/.pikku/rpc/pikku-rpc-wirings-meta.internal.gen.js',
        '@acme/addon/.pikku/function/pikku-functions-meta.gen.js',
        '@acme/addon/.pikku/permissions/pikku-permissions.gen.js',
        '@acme/addon/.pikku/pikku-package.gen.js',
      ],
      deferred: [
        '@acme/addon/.pikku/schemas/register.gen.js',
        '@acme/addon/.pikku/function/pikku-functions.gen.js',
      ],
    })
  })

  test('a bootstrap it does not recognise is imported whole', () => {
    assert.equal(
      splitAddonBootstrap(
        '@acme/addon',
        `${addonBootstrap}export const extra = registerSomething()\n`
      ),
      null
    )
  })

  test('a bootstrap with nothing to defer is imported whole', () => {
    assert.equal(
      splitAddonBootstrap(
        '@acme/addon',
        `import './function/pikku-functions-meta.gen.js'\n`
      ),
      null
    )
  })
})

describe('serializeLoadAddons', () => {
  // The deploy entry awaits it on every path, so it has to exist and register
  // once however many requests race to it.
  test('imports each deferred file once, on first call', async () => {
    const source = serializeLoadAddons([
      '@acme/addon/.pikku/schemas/register.gen.js',
    ])
    assert.match(source, /export const loadAddons = /)
    assert.match(source, /addonsLoaded \?\?= Promise\.all\(\[/)
    assert.match(
      source,
      /import\('@acme\/addon\/\.pikku\/schemas\/register\.gen\.js'\)/
    )
    assert.doesNotMatch(source, /^import '/m)
  })

  test('is emitted with nothing to load', () => {
    assert.match(serializeLoadAddons([]), /Promise\.all\(\[\n {2}\]\)/)
  })
})
